const DEPARTAMENTOS = ['AMAZONAS','ANCASH','APURIMAC','AREQUIPA','AYACUCHO','CAJAMARCA','CALLAO','CUSCO','HUANCAVELICA','HUANUCO','ICA','JUNIN','LA LIBERTAD','LAMBAYEQUE','LIMA','LORETO','MADRE DE DIOS','MOQUEGUA','PASCO','PIURA','PUNO','SAN MARTIN','TACNA','TUMBES','UCAYALI'];
const MENU = 'Hola, soy el asistente de LiciHub. Puedo buscar licitaciones abiertas o dejar tus datos para que te contacte un asesor.\n\nEscribe licitaciones o asesor. /cancelar vuelve a empezar.';

function normalizar(valor) {
  return String(valor || '').toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
}
function departamento(texto) {
  const n = normalizar(texto);
  return DEPARTAMENTOS.find((d) => normalizar(d) === n) || null;
}
function correo(valor) {
  const v = String(valor || '').trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) && v.length <= 254 ? v : '';
}
function telefono(valor) {
  const v = String(valor || '').trim();
  return /^[+\d\s()\-]{6,30}$/.test(v) ? v : '';
}
function recortar(valor, max) {
  return String(valor || '').trim().slice(0, max);
}

const mensaje = $json.message || {};
const chat = mensaje.chat || {};
if (chat.type !== 'private' || !Number.isSafeInteger(chat.id) || chat.id <= 0) return [];
const updateId = $json.update_id;
if (!Number.isSafeInteger(updateId)) return [];
let texto = typeof mensaje.text === 'string' ? mensaje.text.trim() : '';
if (!texto || texto.length > 500) {
  return [{json:{accion:'responder', chatId:String(chat.id), texto:'Escríbeme un mensaje de texto de hasta 500 caracteres.'}}];
}

const memoria = $getWorkflowStaticData('global');
memoria.vistos = memoria.vistos || {};
if (memoria.vistos[updateId]) return [];
memoria.vistos[updateId] = Date.now();
const vistos = Object.entries(memoria.vistos).sort((a, b) => a[1] - b[1]);
while (vistos.length > 400) {
  delete memoria.vistos[vistos.shift()[0]];
}
memoria.sesiones = memoria.sesiones || {};
const chatId = String(chat.id);
const ahora = Date.now();
let sesion = memoria.sesiones[chatId];
if (!sesion || ahora - (sesion.actualizado || 0) > 12 * 60 * 60 * 1000) {
  sesion = {estado:'menu'};
}
sesion.actualizado = ahora;
const n = normalizar(texto);
const comando = n.split(' ')[0].replace(/@\w+$/, '');
const reinicio = ['/start','/cancelar','cancelar','menu','hola','buenas'].includes(comando) || n === 'hola';
const pideBusqueda = ['/licitaciones','licitaciones','licitacion','buscar'].includes(comando);
const pideAsesor = ['/asesor','asesor','asesoria','cotizar','cotizacion'].includes(comando);

function guardar() {
  memoria.sesiones[chatId] = sesion;
  const ids = Object.entries(memoria.sesiones).sort((a, b) => (a[1].actualizado || 0) - (b[1].actualizado || 0));
  while (ids.length > 200) delete memoria.sesiones[ids.shift()[0]];
}
function responder(salida) {
  guardar();
  return [{json:{accion:'responder', chatId, texto:salida}}];
}

if (reinicio) {
  const licitacion = sesion.licitacion || '';
  sesion = {estado:'menu', actualizado:ahora, licitacion};
  return responder(MENU);
}
if (pideBusqueda) {
  sesion.estado = 'busqueda';
  return responder('Dime un departamento del Perú o palabras de lo que buscas. Ejemplo: Lima, o cemento portland.');
}
if (pideAsesor) {
  sesion.estado = 'empresa';
  return responder('Para que te contacte un asesor, escribe la razón social de tu empresa.');
}
if (comando === '/estado') {
  return responder(sesion.solicitud ? 'Tu última solicitud quedó registrada como ' + sesion.solicitud + '.' : 'Todavía no envío una solicitud en esta conversación.');
}

if (sesion.estado === 'busqueda') {
  const dep = departamento(texto);
  const palabras = dep ? [] : normalizar(texto).split(' ').filter((p) => p.length >= 3).slice(0, 8);
  const busqueda = {p_modo: palabras.length || sesion.ruc ? 'perfil' : 'todas', p_orden:'afinidad', p_limite:3, p_offset:0};
  if (sesion.ruc) busqueda.p_ruc = sesion.ruc;
  if (dep) busqueda.p_departamento = dep;
  if (palabras.length) {
    busqueda.p_keywords = palabras;
    busqueda.p_q = palabras.join(' ');
  }
  sesion.estado = 'menu';
  guardar();
  return [{json:{accion:'buscar', chatId, busqueda}}];
}

if (sesion.estado === 'empresa') {
  if (texto.length < 2) return responder('La razón social necesita al menos 2 caracteres.');
  sesion.empresa = recortar(texto, 160);
  sesion.estado = 'ruc';
  return responder('Escribe el RUC de 11 dígitos, o omitir si aún no lo tienes.');
}
if (sesion.estado === 'ruc') {
  if (n !== 'omitir' && !/^\d{11}$/.test(texto)) return responder('El RUC debe tener 11 dígitos. Si no lo tienes, escribe omitir.');
  sesion.ruc = n === 'omitir' ? '' : texto;
  sesion.estado = 'contacto';
  return responder('¿A nombre de quién pedimos el contacto?');
}
if (sesion.estado === 'contacto') {
  if (texto.length < 2) return responder('Escribe el nombre de la persona de contacto.');
  sesion.contacto = recortar(texto, 100);
  sesion.estado = 'medio';
  return responder('Déjame un correo o un teléfono.');
}
if (sesion.estado === 'medio') {
  const email = correo(texto);
  const phone = telefono(texto);
  if (!email && !phone) return responder('No reconocí un correo ni un teléfono. Escríbelo de nuevo.');
  sesion.email = email;
  sesion.telefono = email ? '' : phone;
  sesion.estado = 'servicio';
  return responder('¿Qué servicio necesitas? Por ejemplo: Certificación ISO 9001.');
}
if (sesion.estado === 'servicio') {
  if (texto.length < 2) return responder('Describe el servicio en una frase.');
  sesion.servicio = recortar(texto, 160);
  sesion.estado = 'tipo';
  return responder('Responde 1 para asesoría o 2 para cotización.');
}
if (sesion.estado === 'tipo') {
  if (!['1','2','asesoria','cotizacion'].includes(n)) return responder('Responde 1 para asesoría o 2 para cotización.');
  sesion.tipo = (n === '2' || n === 'cotizacion') ? 'quote' : 'advice';
  sesion.estado = 'confirmar';
  const medio = sesion.email || sesion.telefono;
  return responder('Voy a enviar esto al equipo comercial de LiciHub:\nEmpresa: ' + sesion.empresa + '\nRUC: ' + (sesion.ruc || 'sin RUC') + '\nContacto: ' + sesion.contacto + '\nMedio: ' + medio + '\nServicio: ' + sesion.servicio + '\nTipo: ' + (sesion.tipo === 'quote' ? 'cotización' : 'asesoría') + (sesion.licitacion ? '\nLicitación: ' + sesion.licitacion : '') + '\n\nResponde SI para enviarlo. Otra respuesta lo cancela.');
}
if (sesion.estado === 'confirmar') {
  if (!['si','s','ok','dale'].includes(n)) {
    sesion.estado = 'menu';
    return responder('Listo, no envié la solicitud. Escribe licitaciones o asesor cuando quieras.');
  }
  const usuario = mensaje.from && mensaje.from.username;
  const notas = ['Solicitud del bot de Telegram en n8n, sin cuenta del portal.', 'La persona confirmó el envío de sus datos al equipo comercial.'];
  if (/^[A-Za-z0-9_]{5,32}$/.test(usuario || '')) notas.push('Contacto Telegram: https://t.me/' + usuario);
  const solicitud = 'n8n:' + chatId + ':' + updateId;
  const crm = {requestId: solicitud, payload:{
    company: sesion.empresa,
    ruc: sesion.ruc || '',
    contact: sesion.contacto,
    email: sesion.email || '',
    phone: sesion.telefono || '',
    origin: 'Telegram',
    kind: sesion.tipo,
    service: sesion.servicio,
    evidence: 'none',
    tender: recortar(sesion.licitacion || '', 160),
    notes: notas.join('\n').slice(0, 3000)
  }};
  sesion.solicitud = solicitud;
  sesion.estado = 'menu';
  guardar();
  return [{json:{accion:'enviar_crm', chatId, crm}}];
}

sesion.estado = 'menu';
return responder(MENU);

const previo = $('Conversación').first().json;
const chatId = String(previo.chatId);
function filasDe(item) {
  const cuerpo = item.json && item.json.body !== undefined ? item.json.body : item.json;
  return Array.isArray(cuerpo) ? cuerpo : [];
}
const filas = $input.all().flatMap(filasDe).filter((fila) => fila && (fila.convocatoria_id || fila.descripcion || fila.licitacion));
if (!filas.length) {
  return [{json:{chatId, consultar:false, texto:'No encontré licitaciones abiertas con ese criterio. Prueba otro departamento o palabras, o escribe asesor.'}}];
}
const config = $('Config').first().json;
const ids = [...new Set(filas.map((fila) => fila.convocatoria_id).filter((id) => /^\d+$/.test(String(id))))].slice(0, 3);
const base = String(config.supabaseUrl || '').replace(/\/$/, '');
const memoria = $getWorkflowStaticData('global');
const sesion = (memoria.sesiones || {})[chatId] || {estado:'menu'};
const primera = filas[0];
sesion.licitacion = String(primera.licitacion || primera.nomenclatura || primera.nomenclatura_norm || '').slice(0, 160);
sesion.estado = 'menu';
sesion.actualizado = Date.now();
memoria.sesiones[chatId] = sesion;
return [{json:{chatId, consultar: ids.length > 0, filas, fichasUrl: base + '/rest/v1/convocatorias?select=id,ver_proceso_url,licitacion,nomenclatura_norm&id=in.(' + ids.join(',') + ')'}}];

const previo = $('Preparar fichas').first().json;
const enlaces = {};
function filasDe(item) {
  const cuerpo = item.json && item.json.body !== undefined ? item.json.body : item.json;
  return Array.isArray(cuerpo) ? cuerpo : (cuerpo && cuerpo.id != null ? [cuerpo] : []);
}
for (const fila of $input.all().flatMap(filasDe)) {
  if (fila.id != null) enlaces[String(fila.id)] = fila.ver_proceso_url || '';
}
const lineas = (previo.filas || []).slice(0, 3).map((fila, indice) => {
  const codigo = fila.licitacion || fila.nomenclatura || fila.nomenclatura_norm || fila.convocatoria_id;
  const titulo = String(fila.descripcion || fila.objeto_descripcion || 'Sin título').slice(0, 180);
  const entidad = fila.entidad || fila.entidad_convocante || '';
  const monto = fila.monto_referencial != null ? fila.monto_referencial + ' ' + (fila.moneda || 'PEN') : '';
  const cierre = fila.fecha_limite ? String(fila.fecha_limite).slice(0, 10) : '';
  const url = enlaces[String(fila.convocatoria_id)] || '';
  return (indice + 1) + '. ' + codigo + ' — ' + titulo + (entidad ? '\n' + entidad : '') + (monto ? '\n' + monto : '') + (cierre ? '\nCierra: ' + cierre : '') + (url ? '\n' + url : '');
});
return [{json:{chatId: previo.chatId, texto: 'Encontré estas licitaciones abiertas:\n\n' + lineas.join('\n\n') + '\n\nEscribe asesor si quieres que te contactemos por alguna, o licitaciones para otra búsqueda.'}}];

const previo = $('Conversación').first().json;
const cuerpo = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const aceptado = ($json.statusCode === undefined || $json.statusCode === 200) && cuerpo.accepted === true;
const texto = aceptado
  ? 'Listo. El equipo comercial recibió tu solicitud ' + previo.crm.requestId + '.'
  : 'No pude entregar la solicitud al CRM. Revisa TU_CRM_API_URL y TU_CRM_INGEST_KEY en el nodo Config y vuelve a confirmar.';
return [{json:{chatId: previo.chatId, texto}}];
